// Robust (generalized / SB-scaled) statistic for one candidate. Reuses the NT
// worker, then rescales by `c = gᵀB1g / gᵀA1g`, where `g` is the same efficient-
// score direction the NT Schur complement implies (`g = d − K(KᵀIK)⁻¹KᵀI d`, so
// `gᵀs = score_eff` and `gᵀI g = info_eff`), and A1/B1 are the parameter-space
// sandwich bread/meat. `mi_scaled = mi / c`; under normality B1 = A1 ⇒ c = 1.
post_expected<ScoreTestResult>
score_for_direction_robust(const ScoreCandidate& candidate,
                           const Eigen::VectorXd& score_full,
                           const Eigen::MatrixXd& info_full,
                           const Eigen::MatrixXd& A1,
                           const Eigen::MatrixXd& B1,
                           const Eigen::MatrixXd& K_nuisance,
                           const Eigen::VectorXd& direction) {
  auto nt = score_for_direction(candidate, score_full, info_full, K_nuisance,
                                direction);
  if (!nt.has_value()) return nt;

  const Eigen::Index q = score_full.size();
  if (A1.rows() != q || A1.cols() != q || B1.rows() != q || B1.cols() != q) {
    return std::unexpected(make_err(PostError::Kind::NumericIssue,
        "robust score tests: sandwich bread/meat shape mismatch"));
  }

  // Efficient-score direction g (the NT code only needs the two scalars it
  // contracts to, so it never forms g; the robust meat does).
  Eigen::VectorXd g = direction;
  if (K_nuisance.cols() > 0) {
    const Eigen::VectorXd I_d = info_full * direction;
    const Eigen::MatrixXd I_aa = K_nuisance.transpose() * info_full * K_nuisance;
    auto Iaa_inv = invert_symmetric(I_aa, "robust score tests nuisance information");
    if (!Iaa_inv.has_value()) return std::unexpected(Iaa_inv.error());
    g.noalias() -= K_nuisance * ((*Iaa_inv) * (K_nuisance.transpose() * I_d));
  }

  const double bread_q = g.dot(A1 * g);
  const double meat_q = g.dot(B1 * g);
  const double tol = 1e-12 * std::max<double>(1.0, std::abs(bread_q));
  if (!(bread_q > tol) || !std::isfinite(meat_q) || !(meat_q > 0.0)) {
    return std::unexpected(make_err(PostError::Kind::InfoMatrixSingular,
        "robust score tests: sandwich quadratic form is not positive"));
  }

  const double c = meat_q / bread_q;
  ScoreTestResult out = *nt;
  out.scaling_factor = c;
  out.v_eff = out.information * c;   // robust efficient-score variance (NT units)
  out.mi_scaled = out.mi / c;
  out.p_value = chi2_pvalue(out.mi_scaled, out.df);
  return out;
}

post_expected<JointScoreTestResult>
score_for_subspace_robust(std::vector<ScoreCandidate> candidates,
                          const Eigen::VectorXd& score_full,
                          const Eigen::MatrixXd& info_full,
                          const Eigen::MatrixXd& A1,
                          const Eigen::MatrixXd& B1,
                          const Eigen::MatrixXd& K_nuisance,
                          const Eigen::MatrixXd& directions) {
  const Eigen::Index q = score_full.size();
  const Eigen::Index df = directions.cols();
  if (info_full.rows() != q || info_full.cols() != q || directions.rows() != q ||
      A1.rows() != q || A1.cols() != q || B1.rows() != q || B1.cols() != q ||
      K_nuisance.rows() != q || df < 1) {
    return std::unexpected(make_err(PostError::Kind::NumericIssue,
        "robust joint score test: incompatible subspace shapes"));
  }

  // Efficient-score subspace: each release direction made info-orthogonal to the
  // nuisance subspace. G = D − K (KᵀIK)⁻¹ Kᵀ I D (the matrix form of the
  // per-direction g, so u = Gᵀs and V = GᵀIG are the Schur-reduced score/info).
  Eigen::MatrixXd G = directions;
  if (K_nuisance.cols() > 0) {
    const Eigen::MatrixXd I_d = info_full * directions;  // q × df
    const Eigen::MatrixXd I_aa =
        K_nuisance.transpose() * info_full * K_nuisance;
    auto Iaa_inv =
        invert_symmetric(I_aa, "robust joint score test nuisance information");
    if (!Iaa_inv.has_value()) return std::unexpected(Iaa_inv.error());
    G.noalias() -= K_nuisance * ((*Iaa_inv) * (K_nuisance.transpose() * I_d));
  }

  // NT joint (multivariate score) statistic T = uᵀ V⁻¹ u.
  const Eigen::VectorXd u = G.transpose() * score_full;  // df
  Eigen::MatrixXd V = G.transpose() * (info_full * G);   // df × df
  V = 0.5 * (V + V.transpose());
  auto V_inv =
      invert_symmetric(V, "robust joint score test efficient information");
  if (!V_inv.has_value()) return std::unexpected(V_inv.error());
  const double T = u.dot((*V_inv) * u);
  if (!std::isfinite(T) || T < 0.0) {
    return std::unexpected(make_err(PostError::Kind::NumericIssue,
        "robust joint score test: NT statistic is not finite/nonnegative"));
  }

  // Generalized spectrum λ of (GᵀA1G)⁻¹(GᵀB1G): the χ²₁ mixture weights.
  Eigen::MatrixXd GtA = G.transpose() * (A1 * G);
  Eigen::MatrixXd GtB = G.transpose() * (B1 * G);
  GtA = 0.5 * (GtA + GtA.transpose());
  GtB = 0.5 * (GtB + GtB.transpose());
  Eigen::GeneralizedSelfAdjointEigenSolver<Eigen::MatrixXd> ges(GtB, GtA);
  if (ges.info() != Eigen::Success) {
    return std::unexpected(make_err(PostError::Kind::InfoMatrixSingular,
        "robust joint score test: generalized eigensolver failed (GtA not PD?)"));
  }
  const Eigen::VectorXd lambda = ges.eigenvalues();  // ascending
  const double trace = lambda.sum();

  JointScoreTestResult out;
  out.candidates = std::move(candidates);
  out.df = static_cast<int>(df);
  out.mi = T;
  out.eigvals = lambda;
  // Unlike mean scaling or a plug-in mixture tail, this quadratic uses the
  // full efficient-score meat as its studentizer and is asymptotically
  // pivotal under the sandwich regularity conditions. Keep the established
  // spectrum results available when a finite-sample meat is only PSD.
  // A1/B1 may be per-case or moment-weight scaled while score_full/info_full
  // are totals. Mean scaling is invariant to that common scale; the direct
  // quadratic is not. Map the sandwich bread to V's score scale, then apply
  // the same map to its meat. The supported evaluators construct proportional
  // breads, so the Frobenius projection is exact up to rounding.
  const double bread_norm_sq = GtA.squaredNorm();
  const double bread_scale = bread_norm_sq > 0.0
      ? V.cwiseProduct(GtA).sum() / bread_norm_sq
      : std::numeric_limits<double>::quiet_NaN();
  const Eigen::MatrixXd B_score = bread_scale * GtB;
  auto GtB_inv = invert_symmetric(
      B_score, "robust joint score test efficient sandwich variance");
  if (GtB_inv.has_value()) {
    const double T_sandwich = u.dot((*GtB_inv) * u);
    if (std::isfinite(T_sandwich) && T_sandwich >= 0.0) {
      out.mi_sandwich = T_sandwich;
      out.p_sandwich = chi2_pvalue(T_sandwich, out.df);
      out.sandwich_available = true;
      Eigen::SelfAdjointEigenSolver<Eigen::MatrixXd> bes(B_score);
      if (bes.info() == Eigen::Success) {
        out.sandwich_min_eigenvalue = bes.eigenvalues().minCoeff();
        out.sandwich_condition = bes.eigenvalues().maxCoeff() /
                                 out.sandwich_min_eigenvalue;
      }
    }
  }
  if (std::isfinite(trace) && trace > 0.0) {
    out.scaling_factor = trace / static_cast<double>(df);  // c̄ = Σλ / df
    out.mi_scaled = T / out.scaling_factor;
    out.p_value = chi2_pvalue(out.mi_scaled, out.df);
    out.p_mixture = robust::weighted_chisq_upper(lambda, T);
  } else {
    out.scaling_factor = 1.0;
    out.mi_scaled = T;
    out.p_value = chi2_pvalue(T, out.df);
    out.p_mixture = out.p_value;
  }
  return out;
}

